demo.appDue:
def done(self, index):
    self.todos[index]['done'] = True

def due(self, index, date):
    # 마감일 지정 (작업 중)
    self.todos[index]['due'] = date
    self.save()

def overdue(self, today):
    return [t for t in self.todos if t.get('due') and t['due'] < today]

